#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
WRITTEN_REMOTE=() # HOST:PATHs written by write_remote this run
SKIPPED=()        # things we couldn't do (e.g. gh/glab missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" [REGEX] is like ask, but input is hidden. A paste that
# wrapped onto several lines is joined back into one value. If REGEX is given,
# a value that doesn't match it is rejected. Then it shows the length and last
# 4 chars and asks the human to confirm, which catches truncated and doubled
# pastes. A rejected value is asked for again.
ask_secret() {
  local key="$1" prompt="$2" pattern="${3:-}" current input more tail rc
  current=$(_existing "$key" || true)
  while :; do
    rc=0
    if [[ -n "$current" ]]; then
      printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
    else
      printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
    fi
    read -rs input || rc=1
    # Lines arriving within a second are the rest of the same paste.
    if [[ -t 0 ]]; then
      while IFS= read -rs -t 1 more; do input+="${more%$'\r'}"; done
    fi
    printf '\n'
    if (( rc )) && [[ -z "$input" ]]; then return 1; fi
    [[ -z "$input" && -n "$current" ]] && input="$current"
    if [[ -n "$pattern" && ! "$input" =~ $pattern ]]; then
      warn "that doesn't look right (${#input} chars, expected format $pattern)"
      current=""; continue
    fi
    tail=""; (( ${#input} >= 16 )) && tail=", ending …${input: -4}"
    note "got ${#input} chars$tail"
    confirm "Does that match what you copied?" && break
    current=""
  done
  printf -v "$key" '%s' "$input"
}

# fingerprint VALUE prints a short sha256 of VALUE: safe to show and compare.
fingerprint() {
  printf '%s' "$1" | { sha256sum 2>/dev/null || shasum -a 256; } | cut -c1-16
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# write_remote HOST PATH CONTENT writes CONTENT plus a newline to PATH on HOST
# over ssh stdin, so the value stays out of argv. The write is atomic, the file
# is mode 0600 and a directory it creates is 0700, set by chmod because some
# filesystems (UGREEN's ugacl mounts) ignore umask. It then reads back a
# fingerprint and the mode, and passes only if the stored file matches what was
# sent and is 0600; a write that silently changed nothing, or left the file
# readable by others, fails.
write_remote() {
  local host="$1" path="$2" content="$3" q sent stored=""
  printf -v q '%q' "$path"
  sent=$(fingerprint "$content"$'\n')
  if printf '%s\n' "$content" |
       ssh -o BatchMode=yes "$host" "umask 077; d=\$(dirname $q); [ -d \"\$d\" ] || { mkdir -p \"\$d\" && chmod 700 \"\$d\"; }; : > $q.tmp && chmod 600 $q.tmp && cat > $q.tmp && mv $q.tmp $q"; then
    # -n: only the write above may read stdin; a check that inherits the
    # terminal swallows whatever the human types next.
    stored=$(ssh -n -o BatchMode=yes "$host" "printf '%s %s' \"\$({ sha256sum || shasum -a 256; } < $q 2>/dev/null | cut -c1-16)\" \"\$(stat -c %a $q 2>/dev/null || stat -f %Lp $q)\"" || true)
  fi
  if [[ -n "$stored" && "$stored" == "$sent 600" ]]; then
    WRITTEN_REMOTE+=("$host:$path")
    printf '  %s✓ wrote%s %s:%s %s(verified %s)%s\n' "$GREEN" "$RESET" "$host" "$path" "$DIM" "$sent" "$RESET"
    return
  fi
  SKIPPED+=("$host:$path (write unverified: expected $sent 600, stored ${stored:-nothing})")
  warn "couldn't verify $host:$path: expected $sent 600 (fingerprint, mode), stored ${stored:-nothing}"
}

# _ci prints the CI host that set_secret/set_var write to: github or gitlab.
# Read from the origin remote's URL; set CI_HOST to override (e.g. a
# self-hosted GitLab whose URL doesn't say "gitlab").
_ci() {
  if [[ -n "${CI_HOST:-}" ]]; then printf '%s' "$CI_HOST"; return; fi
  case "$(git remote get-url origin 2>/dev/null)" in
    *github.com*) printf github ;;
    *gitlab*)     printf gitlab ;;
  esac
}

# _ci_label github|gitlab prints the host's display name.
_ci_label() { case "$1" in github) printf GitHub ;; gitlab) printf GitLab ;; esac; }

# _ready TOOL: TOOL is installed and authenticated.
_ready() { command -v "$1" >/dev/null 2>&1 && "$1" auth status >/dev/null 2>&1; }

# set_secret NAME VALUE stores a CI secret: a GitHub Actions repo secret, or a
# GitLab CI/CD variable that's masked, hidden and raw (no $ expansion). Falls
# back to a warning (and records it) if the CLI is missing or unauthenticated,
# or if GitLab rejects the value for masking (one line, 8+ chars, limited set).
set_secret() {
  local name="$1" value="$2" ci; ci=$(_ci)
  case "$ci" in
    github) _ready gh && printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1 ;;
    gitlab) _ready glab && {
              printf '%s' "$value" | glab variable set "$name" --masked --hidden --raw >/dev/null 2>&1 ||
              printf '%s' "$value" | glab variable update "$name" --masked --raw >/dev/null 2>&1; } ;;
    *) false ;;
  esac && {
    WRITTEN_SECRET+=("$name")
    printf '  %s✓ set%s %s secret %s\n' "$GREEN" "$RESET" "$(_ci_label "$ci")" "$name"
    return
  }
  local why="CLI not ready or value rejected"
  [[ -n "$(_ci_label "$ci")" ]] || why="CI host ${ci:-unknown}; set CI_HOST=github|gitlab"
  SKIPPED+=("CI secret $name ($why)")
  warn "skipped CI secret $name ($why); set it by hand later"
}

# set_var NAME VALUE sets a CI variable (non-secret) on GitHub or GitLab.
set_var() {
  local name="$1" value="$2" ci; ci=$(_ci)
  case "$ci" in
    github) _ready gh && gh variable set "$name" --body "$value" >/dev/null 2>&1 ;;
    gitlab) _ready glab && {
              glab variable set "$name" -v "$value" --raw >/dev/null 2>&1 ||
              glab variable update "$name" -v "$value" --raw >/dev/null 2>&1; } ;;
    *) false ;;
  esac && {
    printf '  %s✓ set%s %s variable %s\n' "$GREEN" "$RESET" "$(_ci_label "$ci")" "$name"
    return
  }
  local why="CLI not ready"
  [[ -n "$(_ci_label "$ci")" ]] || why="CI host ${ci:-unknown}; set CI_HOST=github|gitlab"
  SKIPPED+=("CI variable $name ($why)")
  warn "skipped CI variable $name ($why); set it by hand later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} CI secret(s): ${WRITTEN_SECRET[*]}"
  (( ${#WRITTEN_REMOTE[@]} )) && note "wrote ${#WRITTEN_REMOTE[@]} remote file(s): ${WRITTEN_REMOTE[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6

ORG=netalondon-jellyfin-plugins
CATALOG=plugin-repository
NEW_TOKEN_URL=https://github.com/settings/personal-access-tokens/new
TOKENS_URL=https://github.com/settings/personal-access-tokens
REQUESTS_URL="https://github.com/organizations/$ORG/settings/personal-access-token-requests"
TOKEN_FORMAT='^github_pat_[A-Za-z0-9_]+$'
# The secrets go to GitHub, though this checkout's origin may be GitLab.
export CI_HOST=github
STORED=()
EXPIRES=()

if ! gh auth status >/dev/null 2>&1 || ! gh api "orgs/$ORG" --silent </dev/null >/dev/null 2>&1; then
  warn "Install gh and sign it in (gh auth login) as an owner of $ORG, then run this again."
  exit 1
fi

# The plugin repositories on GitHub: the plugins in plugins.json that have a repository in $ORG.
PLUGIN_REPOS=()
org_repos=$(gh repo list "$ORG" --limit 1000 --json name -q '.[].name' </dev/null)
while IFS= read -r repo; do
  if grep -qxF "$repo" <<< "$org_repos"; then PLUGIN_REPOS+=("$repo"); fi
done < <(gh api "repos/$ORG/$CATALOG/contents/plugins.json" -H 'Accept: application/vnd.github.raw+json' \
           -q '.[] | .repo // (.project | split("/") | last)' </dev/null)
if (( ${#PLUGIN_REPOS[@]} == 0 )); then
  warn "Found none of the plugins in $CATALOG's plugins.json among $ORG's repositories."
  exit 1
fi

# updated REPO NAME prints when REPO's Actions secret NAME last changed, or nothing if it isn't set.
updated() {
  gh secret list -R "$ORG/$1" --json name,updatedAt -q ".[] | select(.name == \"$2\") | .updatedAt" \
    </dev/null 2>/dev/null || true
}

# store REPO NAME VALUE sets REPO's Actions secret NAME. GitHub never shows a secret's value, so
# the secret's update time is the check that it landed.
store() {
  local repo="$1" name="$2" before after
  before=$(updated "$repo" "$name")
  GH_REPO="$ORG/$repo" set_secret "$name" "$3"
  after=$(updated "$repo" "$name")
  if [[ -n "$after" && "$after" != "$before" ]]; then
    STORED+=("$name in $repo")
    note "$repo shows it updated at $after"
  else
    SKIPPED+=("$name in $repo (GitHub doesn't show it updated)")
    warn "$repo doesn't show $name as updated"
  fi
}

# skip N moves the progress count past N stages this run doesn't need.
skip() { _STAGE_INDEX=$((_STAGE_INDEX + $1)); }

# unreadable TOKEN prints each plugin repository whose contents TOKEN can't read.
unreadable() {
  local repo
  for repo in "${PLUGIN_REPOS[@]}"; do
    GH_TOKEN="$1" gh api "repos/$ORG/$repo/contents" --silent </dev/null >/dev/null 2>&1 ||
      printf '%s ' "$repo"
  done
}

# expiry TOKEN prints when TOKEN expires, from the header GitHub adds to each response to it.
expiry() {
  GH_TOKEN="$1" gh api -i "repos/$ORG/$CATALOG" </dev/null 2>/dev/null | tr -d '\r' |
    sed -n 's/^[Gg]ithub-[Aa]uthentication-[Tt]oken-[Ee]xpiration: *//p' || true
}

banner "GitHub tokens for the Jellyfin plugin catalog"

# ── PLUGIN_READ_TOKEN ─────────────────────────────────────────────────────
stage "Read token: create"
say "PLUGIN_READ_TOKEN lets $CATALOG's collect workflow read each plugin's"
say "manifest.json and release zips, since the plugin repositories are private."
make_token=yes
read_updated=$(updated "$CATALOG" PLUGIN_READ_TOKEN)
if [[ -n "$read_updated" ]]; then
  note "It's already set in $CATALOG, updated $read_updated."
  confirm "Replace it with a new token?" || make_token=no
fi

if [[ "$make_token" == yes ]]; then
  printf '\n'
  open_url "$NEW_TOKEN_URL?name=Jellyfin+catalog%3A+read+plugins&description=PLUGIN_READ_TOKEN+secret+in+plugin-repository.+Its+collect+workflow+reads+plugin+manifests+and+release+zips.&target_name=$ORG&expires_in=366&contents=read"
  step "Check that Resource owner is $ORG and Expiration is filled in"
  say  "  (366 days, the longest the organization allows)."
  step "Repository access: All repositories, so plugins added later are covered too."
  step "Permissions: Contents is Read-only (filled in); Metadata: Read-only comes with it."
  step "Click Generate token and copy the token. GitHub shows it only once."
  ask_secret PLUGIN_READ_TOKEN "Paste the token:" "$TOKEN_FORMAT"

  stage "Read token: approve and test"
  while :; do
    say "Reading each plugin repository with the token…"
    failed=$(unreadable "$PLUGIN_READ_TOKEN")
    [[ -z "$failed" ]] && break
    if [[ "$failed" == "$(printf '%s ' "${PLUGIN_REPOS[@]}")" ]]; then
      warn "It can't read any of them. It may be waiting for an organization owner's approval."
      open_url "$REQUESTS_URL"
      step "If a request named \"Jellyfin catalog: read plugins\" is there, approve it."
      note "If nothing is waiting, check the token's resource owner and Contents permission"
      note "at $TOKENS_URL."
    else
      warn "It can't read: $failed"
      open_url "$TOKENS_URL"
      step "Open \"Jellyfin catalog: read plugins\" and set Repository access to All repositories."
    fi
    pause "Press Enter to test again"
  done
  printf '  %s✓%s it reads all %s plugin repositories\n' "$GREEN" "$RESET" "${#PLUGIN_REPOS[@]}"
  expires=$(expiry "$PLUGIN_READ_TOKEN")
  EXPIRES+=("PLUGIN_READ_TOKEN expires ${expires:-on the date shown at $TOKENS_URL}")
  pause "Press Enter to store it in $CATALOG"

  stage "Read token: store"
  store "$CATALOG" PLUGIN_READ_TOKEN "$PLUGIN_READ_TOKEN"
else
  skip 2
fi

# ── CATALOG_DISPATCH_TOKEN (optional) ─────────────────────────────────────
printf '\n'
say "CATALOG_DISPATCH_TOKEN is optional. In a plugin repository, it lets a release start"
say "$CATALOG's collect workflow at once; without it, the 15-minute schedule picks it up."
already=""
for repo in "${PLUGIN_REPOS[@]}"; do
  if [[ -n "$(updated "$repo" CATALOG_DISPATCH_TOKEN)" ]]; then already+="$repo "; fi
done
question="Set it up now?"
if [[ -n "$already" ]]; then
  note "It's already set in: $already"
  question="Replace it with a new token?"
fi

if confirm "$question"; then
  stage "Dispatch token: create"
  say "CATALOG_DISPATCH_TOKEN can only start and enable workflows in $CATALOG."
  open_url "$NEW_TOKEN_URL?name=Jellyfin+catalog%3A+start+collect&description=CATALOG_DISPATCH_TOKEN+secret+in+plugin+repositories.+Their+release+workflows+start+the+plugin-repository+collect+workflow.&target_name=$ORG&expires_in=366&actions=write"
  step "Check that Resource owner is $ORG and Expiration is filled in (366 days)."
  step "Repository access: Only select repositories, then pick $CATALOG."
  step "Permissions: Actions is Read and write (filled in)."
  step "Click Generate token and copy the token. GitHub shows it only once."
  ask_secret CATALOG_DISPATCH_TOKEN "Paste the token:" "$TOKEN_FORMAT"

  stage "Dispatch token: approve and test"
  while :; do
    say "Testing the token on $CATALOG's collect workflow…"
    # Enabling a workflow that's already active changes nothing and takes the same Actions write
    # access as starting it. Release workflows enable it too, in case GitHub disabled it.
    if ! GH_TOKEN="$CATALOG_DISPATCH_TOKEN" gh api -X PUT "repos/$ORG/$CATALOG/actions/workflows/collect.yml/enable" \
         --silent </dev/null >/dev/null 2>&1; then
      warn "It can't manage $CATALOG's workflows. It may be waiting for an organization owner's approval."
      open_url "$REQUESTS_URL"
      step "If a request named \"Jellyfin catalog: start collect\" is there, approve it."
      note "If nothing is waiting, check at $TOKENS_URL that it has"
      note "Actions: Read and write on $CATALOG."
    elif GH_TOKEN="$CATALOG_DISPATCH_TOKEN" gh api "repos/$ORG/${PLUGIN_REPOS[0]}" --silent </dev/null >/dev/null 2>&1; then
      warn "It can read ${PLUGIN_REPOS[0]}, so it reaches more than $CATALOG."
      open_url "$TOKENS_URL"
      step "Open \"Jellyfin catalog: start collect\" and set Repository access to"
      say  "  Only select repositories, with just $CATALOG."
    else
      break
    fi
    pause "Press Enter to test again"
  done
  printf '  %s✓%s it can start %s'\''s workflows and reads no plugin repository\n' "$GREEN" "$RESET" "$CATALOG"
  expires=$(expiry "$CATALOG_DISPATCH_TOKEN")
  EXPIRES+=("CATALOG_DISPATCH_TOKEN expires ${expires:-on the date shown at $TOKENS_URL}")
  pause "Press Enter to choose where to store it"

  stage "Dispatch token: store"
  say "Each plugin repository whose release workflow should start collect needs it."
  say "Plugin repositories on GitHub: ${PLUGIN_REPOS[*]}"
  targets=()
  if confirm "Store it in all of them?"; then
    targets=("${PLUGIN_REPOS[@]}")
  else
    ask DISPATCH_REPOS "Which ones? Names separated by spaces:"
    read -r -a targets <<< "$DISPATCH_REPOS"
  fi
  if (( ${#targets[@]} == 0 )); then
    SKIPPED+=("CATALOG_DISPATCH_TOKEN (no repository chosen)")
    warn "No repository chosen, so it's stored nowhere"
  else
    for repo in "${targets[@]}"; do
      store "$repo" CATALOG_DISPATCH_TOKEN "$CATALOG_DISPATCH_TOKEN"
    done
  fi
  pause
fi

finish
if (( ${#STORED[@]} )); then
  note "Stored:"
  for s in "${STORED[@]}"; do note "  - $s"; done
fi
if (( ${#EXPIRES[@]} )); then
  for s in "${EXPIRES[@]}"; do note "$s"; done
  printf '\n'
  say "Run scripts/setup-tokens.sh again before then. Once a new token replaces an old"
  say "one, delete the old one at $TOKENS_URL."
  printf '\n'
fi
}

run_wizard "$@"; exit
